={{ (() => {
  const context = $('Prepare Context').first().json;
  const meeting = $('Validate Meeting Proposal').first().json.output;

  const start = DateTime.fromISO(meeting.startTime).setZone('Africa/Cairo');
  const end = DateTime.fromISO(meeting.endTime).setZone('Africa/Cairo');
  const duration = end.diff(start, 'minutes').minutes;

  const text = [
    'Please review your meeting:',
    '',
    `Employee: ${context.employeeName}`,
    `Team Lead: ${context.leadName}`,
    `Meeting: ${meeting.eventTitle}`,
    `Description: ${meeting.eventDescription}`,
    `Date: ${start.toFormat('dd LLL yyyy')}`,
    `Start Time: ${start.toFormat('h:mm a')}`,
    `End Time: ${end.toFormat('h:mm a')}`,
    `Duration: ${duration} minutes`,
    'Timezone: Africa/Cairo',
    '',
    'Would you like me to book this meeting?',
    'Reply "Yes, book it" to confirm, or tell me what you would like to change.'
  ].join('\n');

  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
})() }}

